-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := 'd9d99066-f7b6-4e47-a7e1-ab84afab99de';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Before the Event: Registration and Rehearsal', 'The existing lessons show how to drive Zoom and StreamYard. This one covers the work that decides whether anyone turns up and whether the first five minutes go smoothly — which is where events are actually won or lost.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Registration, Invitations and Getting People to Turn Up', 'Zoom''s own guide to managing webinar invitations and registration — how people sign up and how you reach them before the day. Under 7 minutes.', 'https://www.youtube.com/watch?v=zNuhMlKL0FI', 1,
      array['Set up registration and decide which questions to ask', 'Send confirmations and reminders that actually get opened', 'Plan for the gap between people registering and people attending'],
      'Registration is not admin. It is the part that decides your attendance, and most first-time hosts treat it as a form to switch on.

THE NUMBER NOBODY WARNS YOU ABOUT: a large share of people who register will not attend. Free events lose more than paid ones, and the gap is normal rather than a sign you did something wrong. Plan for it — invite more than you need, and make the reminders count.

WHAT TO ASK ON THE FORM: as little as possible. Name and email is usually enough. Every extra field loses registrations, and questions you will not act on are just friction. One useful exception is a question like "what do you most want answered?" — it lifts attendance because the person has invested something, and it hands you the agenda.

THE REMINDER SCHEDULE that works: a confirmation immediately, a reminder the day before, and one an hour before with the join link right at the top. That last one does the heavy lifting. Put the link where a thumb finds it without scrolling.

SAY THE TIME ZONE, ALWAYS. Write "3pm EAT" and not just "3pm". If anyone outside Kenya might attend, add a second time. Confusion over time zones is the most common reason a person who genuinely intended to come does not.

AND MAKE JOINING EASY ON A PHONE. Most of your audience will join from one. Test the link yourself on a phone before you send it — if it forces an app install, ten per cent of your attendance disappears at that moment.

APPROVAL SETTINGS: automatic approval for public events, manual only when you genuinely need to vet people. Manual approval on an open event is a queue you will forget to clear, and people who never got approved do not come back.

A PRACTICAL KENYAN NOTE: many attendees will join on mobile data, and video on a bundle is expensive. Say in the reminder that audio-only is fine and that you will share the recording and slides afterwards. It sounds like a small courtesy; it materially raises the number of people who show up and stay.',
      'Set up a registration page for a real or practice webinar with only the fields you will actually use, plus one question about what the attendee wants answered. Write the three reminder messages — confirmation, day before, hour before — with the join link and the time zone in each. Then register yourself with a different email and go through the whole thing on a phone, timing how long it takes from clicking the reminder to being in the room.',
      '[{"question":"Why keep the registration form as short as possible?","options":["Every extra field loses registrations, and unused answers are pure friction","Zoom limits the number of custom questions","Long forms delay the confirmation email","Attendees cannot edit their answers later"],"correct_index":0},{"question":"Which reminder does the most work for attendance?","options":["The one an hour before, with the join link at the top","The confirmation sent at registration","A reminder a week ahead","A follow-up sent after the event"],"correct_index":0}]'::jsonb),
    (v_m1, 'Rehearsing: Practice Session and Backstage', 'Zoom''s own guide to the practice session and backstage — running through everything before a single attendee can see you. Under 5 minutes.', 'https://www.youtube.com/watch?v=ZH0YM4arRyQ', 2,
      array['Use a practice session to test everything before going live', 'Brief panellists on their roles before attendees arrive', 'Have a plan for the failures that actually happen'],
      'The difference between an event that feels professional and one that does not is almost entirely the first three minutes, and those are decided before anyone joins.

WHAT A PRACTICE SESSION IS FOR: hosts and panellists enter the room while attendees cannot see or hear anything. You test audio, video, screen sharing and slides, and you go live deliberately rather than discovering mid-sentence that you were already broadcasting.

THE RUN-THROUGH CHECKLIST, done thirty minutes before, every time:
- Every speaker''s microphone and camera, one at a time
- Screen sharing, with the ACTUAL file open — sharing works, sharing the right window is what fails
- Any video you plan to play, with sound. Playing video through a share is the single most common live failure, so test it or avoid it
- Recording started, and confirmed as recording
- Notifications and messaging apps closed on the sharing machine, because a private message appearing on a shared screen is a genuine professional disaster

BRIEF THE PANELLISTS IN THE PRACTICE SESSION: who speaks when, who watches the chat, who answers Q&A, and what the hand signal is for "wrap up". Three minutes of this prevents most of the awkwardness in a multi-speaker event.

HAVE A SECOND PERSON if you possibly can. A host cannot present and moderate the chat well at the same time. A co-host handling questions, admitting latecomers and watching for "we cannot hear you" is worth more than any equipment upgrade.

PLAN FOR THE FAILURES THAT ACTUALLY HAPPEN, and in Kenya these are specific and predictable: your power goes, your internet drops, or a speaker''s connection degrades mid-sentence. So: a charged phone with a data bundle as a hotspot, a co-host who can take over and keep talking, and slides sent to a second person in advance. If you present from a laptop, know how long its battery lasts. These are not paranoid precautions; they are the reason some hosts get booked again.

AND START ON TIME. Waiting for latecomers punishes the people who showed up promptly and trains everyone to arrive late next time.',
      'Run a full practice session for a real or imagined event. Test every microphone, share a real file, play a short video with sound, and start the recording. Then deliberately break something — unplug the network for ten seconds — and see what happens and how you would recover. Finally write a one-page run sheet: who does what, minute by minute, for the first five minutes.',
      '[{"question":"What is the main purpose of a practice session?","options":["Hosts and panellists can test everything while attendees see and hear nothing","It records a backup version of the event","It lets attendees join early and settle in","It reduces the bandwidth the event uses"],"correct_index":0},{"question":"Why is a co-host worth more than better equipment?","options":["One person cannot present well and moderate chat and questions at the same time","Zoom requires two hosts for webinars","It doubles the attendee limit","The recording quality improves"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Running It So People Stay', 'Attention online is far harder to hold than in a room. These are the two tools that turn an audience watching passively into one that is participating — and the difference shows in how many are still there at the end.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Polls: Getting the Room to Participate', 'Zoom''s own guide to creating and running polls in meetings and webinars. Under 5 minutes.', 'https://www.youtube.com/watch?v=bQfpX-lU5QQ', 1,
      array['Create polls in advance and launch them at the right moment', 'Use a poll to re-engage attention, not just to collect data', 'Share results in a way that adds something'],
      'Nobody watches a talking head online for forty minutes. Attention drops sharply after about ten, and the honest way to hold it is to make people do something.

A POLL IS AN ATTENTION RESET as much as a question. Every time someone clicks, they are back in the room. Two or three across an hour is about right — more than that and it feels like a survey.

BUILD THEM BEFORE THE EVENT. Writing a poll live while everyone waits is exactly the fumbling that makes an event feel amateur. Prepare them, then launch on cue.

WHERE TO PUT THEM:
- ONE NEAR THE START, easy and low-stakes — "which of these best describes you?". It sets the expectation that this is participatory, and it tells you who is actually in the room so you can adjust.
- ONE IN THE MIDDLE, right where attention sags, ideally on the point you most want to land.
- ONE NEAR THE END, if you want a decision or a next step.

MAKE THE QUESTION EASY. Four options at most, no ambiguity, nothing that requires reading a paragraph. A poll people have to think hard about gets abandoned.

SHARE THE RESULTS AND THEN SAY SOMETHING ABOUT THEM. Showing a bar chart and moving on wastes the moment. "Sixty per cent of you said pricing is the blocker — that is exactly what the next section covers" makes the audience feel the event is about them, which is the whole point.

AND KEEP THE ANSWERS. Poll results across several events tell you what your audience actually struggles with, which is free research for your next event, your marketing, or the product you sell afterwards.

A NOTE FOR MOBILE ATTENDEES: polls appear differently on phones and are easy to miss. Say out loud that a poll has appeared and give people twenty seconds — the silence feels long to you and is normal to them.',
      'Write three polls for a real or planned event: one opener that tells you who is in the room, one mid-point question on your key idea, and one closing question about a next step. Keep every one to four options or fewer. Then, for each, write the single sentence you will say after showing the results — that sentence is what makes the poll worth running.',
      '[{"question":"Beyond collecting answers, what does a well-placed poll do?","options":["Resets attention — clicking brings a drifting attendee back into the room","Increases the recording quality","Reduces the bandwidth used by attendees","Prevents attendees from leaving early"],"correct_index":0},{"question":"When should polls be written?","options":["Before the event, so they can be launched on cue without fumbling","Live, so they respond to what attendees say","Immediately after the event, for the follow-up email","During the practice session, with panellists"],"correct_index":0}]'::jsonb),
    (v_m2, 'Chat, Q&A and Handling the Room', 'Zoom''s own guide to raise hand, chat and Q&A in webinars — how attendees speak up and how a host manages it. Under 5 minutes.', 'https://www.youtube.com/watch?v=zIrbcsyDhOk', 2,
      array['Choose between chat, Q&A and raised hands for a given event', 'Moderate questions so the good ones get answered', 'Handle a hostile or off-topic participant calmly'],
      'Chat and Q&A look like the same feature and behave completely differently, and picking wrongly is why some events feel chaotic.

CHAT is conversation. It scrolls, people talk to each other, and it builds atmosphere. It is also where a question you needed to answer disappears in thirty seconds.

Q&A is a queue. Questions sit in a list, can be upvoted by other attendees, and get marked answered. For anything larger than about twenty people, use Q&A for questions and let chat be chat. The upvoting is genuinely useful: it surfaces what most people want asked, so you are not guessing.

RAISED HANDS are for when you want someone to speak aloud. Reserve them for small events or a deliberate segment — unmuting a stranger on a poor connection in front of two hundred people is a risk you should take on purpose, not by accident.

DECIDE THE RULES BEFORE YOU START and say them in the first minute: where questions go, whether you will take them throughout or at the end, and whether chat is open. Ninety seconds of housekeeping prevents most of the mess.

SOMEONE MUST WATCH THE CHAT, and it cannot be the person presenting. This is the co-host''s real job: pulling good questions into the queue, answering the simple ones in writing, and telling the presenter when three people have said they cannot hear.

WHEN NOBODY ASKS ANYTHING — and at first, nobody will — have two questions prepared and say "a question I often get is...". One answered question breaks the silence and others follow. Silence is not disinterest; it is people not wanting to go first.

DIFFICULT PARTICIPANTS: answer the reasonable part of a hostile question briefly and move on rather than debating in front of everyone. For anything abusive, remove them — know where that control is BEFORE you need it, and turn off attendee-to-attendee chat for public events if you are hosting alone. Being the person who handled it calmly is what gets you hired for the next event.

AND END BY SAYING WHAT HAPPENS NEXT: when the recording arrives, where the slides are, how to reach you. That last minute is the one that turns an attendee into a client.',
      'For a real or planned event, write your first-minute housekeeping script covering where questions go and whether chat is open. Prepare two questions to seed the Q&A if nobody asks. Then find and practise using three controls before you need them: mute an attendee, remove an attendee, and disable attendee chat. Knowing where they are under pressure is the whole skill.',
      '[{"question":"Why use Q&A rather than chat for questions at a larger event?","options":["Questions queue up and can be upvoted, so the ones most people want asked surface","Chat is disabled in webinars by default","Q&A messages are private to the host","Chat does not work on mobile devices"],"correct_index":0},{"question":"Nobody is asking questions. What is the right move?","options":["Answer a prepared question yourself — one answered question breaks the silence","End the session early, since there is no interest","Ask attendees repeatedly until someone responds","Unmute a random attendee to prompt them"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
